using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using SportRace.Domain.Entities; using System.Net.Http.Json;
namespace SportRace.Web.Pages.Admin.StartLists;
public class IndexModel:PageModel {private readonly IHttpClientFactory _factory;public List<StartListVm> StartLists{get;set;}=new();public List<Event> Events{get;set;}=new();[TempData]public string? Message{get;set;}public IndexModel(IHttpClientFactory factory)=>_factory=factory;public async Task OnGetAsync(){var c=_factory.CreateClient("SportRaceApi1");StartLists=await c.GetFromJsonAsync<List<StartListVm>>("api/startlists")??new();Events=await c.GetFromJsonAsync<List<Event>>("api/events")??new();}public async Task<IActionResult> OnPostGenerateAsync(int eventId){var r=await _factory.CreateClient("SportRaceApi1").PostAsync($"api/startlists/generate/{eventId}",null);Message=r.IsSuccessStatusCode?"Стартовият списък е генериран.":"Не може да се генерира списък. Проверете дали има регистрации.";return RedirectToPage();}public async Task<IActionResult> OnPostPublishAsync(int id){await _factory.CreateClient("SportRaceApi1").PutAsync($"api/startlists/{id}/publish",null);return RedirectToPage();}public async Task<IActionResult> OnPostDeleteAsync(int id){await _factory.CreateClient("SportRaceApi1").DeleteAsync($"api/startlists/{id}");return RedirectToPage();}public class StartListVm{public int Id{get;set;}public int EventId{get;set;}public string EventName{get;set;}="";public DateTime CreatedAt{get;set;}public bool IsPublished{get;set;}public int EntryCount{get;set;}}
}
